INSERT INTO sections (name, orderIndex, phase) VALUES ('MEDIDAS DA DCAPE A CONSIDERAR NA FASE DE PREPARAÇÃO PRÉVIA À EXECUÇÃO DA OBRA', 1, 'Preparação Prévia');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Medidas a Considerar na Fase Prévia ao início dos trabalhos da Obra', 2, 'Preparação Prévia');
INSERT INTO sections (name, orderIndex, phase) VALUES ('MEDIDAS DA DCAPE A CONSIDERAR NA FASE DE EXECUÇÃO DA OBRA', 3, 'Execução da Obra');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Medidas a Considerar na Fase de Execução da Obra', 4, 'Execução da Obra');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Desarborização, desmatação, limpeza e decapagem dos solos', 5, 'Execução da Obra');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Escavação e movimentação de terras', 6, 'Execução da Obra');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Construção e reabilitação de acessos', 7, 'Execução da Obra');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Circulação de veículos e funcionamento de maquinaria', 8, 'Execução da Obra');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Proteção de Linhas de água, resíduos e águas residuais', 9, 'Execução da Obra');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Acompanhamento arqueológico', 10, 'Execução da Obra');
INSERT INTO sections (name, orderIndex, phase) VALUES ('MEDIDAS DA DCAPE PARA A FASE FINAL DA CONSTRUÇÃO', 11, 'Fase Final');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Medidas para a fase final da construção', 12, 'Fase Final');
INSERT INTO sections (name, orderIndex, phase) VALUES ('MEDIDAS DA DCAPE PARA A FASE DE DESATIVAÇÃO', 13, 'Desativação');
INSERT INTO sections (name, orderIndex, phase) VALUES ('Medidas para a fase final de desativação', 14, 'Desativação');
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('1', 'Cintagem prévia, com tinta indelével, dos sobreiros a abater, nos termos do nº 2 do artigo 9.º do Decreto-Lei n.º 169/2001 de 25 de maio, na sua redação atual e comunicação ao ICNF, com a antecedência mínima de trinta dias úteis em relação à data de início do abate, para efeitos de verificação/fiscalização e ser apresentada a informação cartográfica, em formato shapefile, com a identificação destes exemplares.', 'EE', 2, 1);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('2', 'Sinalizar os exemplares de sobreiros / azinheiras, imediatamente adjacentes às áreas de construção, antes de dar início da mesma, para que estes não sejam afetados pela implementação do projeto, bem como delimitar uma área de proteção dos sobreiros existentes, pelo menos, o dobro da projeção da área da copa, no mínimo de 4 m de raio (árvores jovens), onde são interditas quaisquer ações que conduzam ao seu perecimento ou evidente depreciação (como sejam a remoção de terra vegetal ou mobilizações profundas do solo, etc.), que possam danificar as árvores, nomeadamente as raízes, pernadas, ramos e troncos.', 'DO', 2, 2);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('3', 'No planeamento dos trabalhos e na execução dos mesmos, devem ser adotadas todas as práticas e medidas adequadas de modo a reduzir a formação de poeiras na origem, por compactação e pulverização do solo, visando também a redução dos níveis de perda de carbono e de libertação de poeiras e a sua propagação, como: o não uso de máquinas de rastos; redução das movimentações de terras em períodos de ventos e a exposição de solo nu nos períodos de maior pluviosidade e ventos.', 'DO | EE', 2, 3);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('4', 'Divulgar o programa de execução das obras às populações interessadas, designadamente, as populações mais próximas, mediante divulgação em locais públicos, nomeadamente nas Juntas de Freguesia e nas Câmaras Municipais. A informação disponibilizada deve incluir o objetivo, a natureza, a localização da obra, as principais ações a realizar, respetiva calendarização e eventuais afetações à população, designadamente a afetação temporária das acessibilidades.', 'DO | EE', 2, 4);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('5', 'Implementar um mecanismo de atendimento ao público para a receção de reclamações, sugestões e/ou pedidos de informação sobre o projeto. Este mecanismo deve contemplar pontos de atendimento telefónico e através da internet e estes contactos devem estar afixados, pelo menos, à entrada do estaleiro e em cada frente de obra. As reclamações apresentadas devem ser alvo de análise, avaliação dos impactes associados e, caso se justifique, propostas medidas de minimização ou de eliminação do motivo das mesmas.', 'DO | EE', 2, 5);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('6', 'Realizar ações de formação e de sensibilização ambiental para os trabalhadores e encarregados envolvidos na execução das obras, relativamente às ações suscetíveis de causar impactes ambientais e às medidas de minimização a implementar, designadamente normas e cuidados a ter no decurso dos trabalhos. Estas ações devem realizadas anualmente e sempre que sejam admitidos novos trabalhadores. Neste contexto, deve também ser apresentado o PAAO', 'EE | RAA', 2, 6);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('7', 'Implementar sinalização em toda a área de construção do Data Centre para sensibilização dos cuidados a ter com os habitats, fauna e flora existente.', 'EE', 2, 7);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('8', 'Em todas as áreas sujeitas a intervenção, incluindo os locais de intervenção para a colocação dos apoios das linhas elétricas aéreas, e antes do início de qualquer atividade relacionada com a obra, devem ser estabelecidos os limites para além dos quais não deve haver lugar a qualquer perturbação, quer pelas máquinas quer por eventuais depósitos de terras e/ou outros materiais. Consequentemente, os referidos limites devem ser claramente balizados, e não meramente sinalizados, antes do início da obra, devendo permanecer em todo o perímetro, durante a execução da mesma.', 'EE | RAA', 2, 8);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('9', 'Devem ser salvaguardadas todas as espécies arbóreas e arbustivas que não condicionem a execução da obra, em particular os exemplares adultos de espécies arbóreas autóctones, como sobreiro e azinheira. Para o efeito devem ser implementadas medidas de sinalização das árvores e arbustos, fora das áreas a intervencionar, e que, pela proximidade a estas, se preveja que possam ser acidentalmente afetados. A decisão sobre os exemplares a sinalizar deve ser tomada no local. Esta sinalização deve ser mantida durante o período em que a obra decorre no local de cada apoio.', 'EE | RAA', 2, 9);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('10', 'Informar os Serviços Municipais de Proteção Civil e os Gabinetes Técnicos Florestais, bem como os agentes de proteção civil localmente relevantes (Corpos de Bombeiros, por exemplo), designadamente quanto as ações que serão levadas a cabo e respetiva calendarização, de modo a possibilitar um melhor acompanhamento e intervenção, bem como para ponderar a eventual necessidade de atualização dos correspondentes Planos Municipais de Emergência de Proteção Civil e dos Planos Municipais de Defesa da Floresta Contra Incêndios.', 'DO', 2, 10);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('11', 'Efetuar um planeamento de obra de forma a:', 'EE', 2, 11);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('11.1', 'Minimizar acumulações excessivas de tráfego automóvel originadas pelo encerramento temporário de faixas de rodagem (caso aplicável).', 'EE', 2, 12);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('11.2', 'Reduzir ao mínimo o período em que ocorram movimentações de terras, devendo esta fase decorrer preferencialmente em época seca, de modo a minimizar a erosão dos solos e o transporte sólido nas linhas de água.', 'EE', 2, 13);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('11.3', 'Realizar os trabalhos que envolvam intervenções em linhas de água (inclui atravessamentos e drenagem) numa época do ano adequada, de modo que estas apresentem o mínimo escoamento possível.', 'EE', 2, 14);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('11.4', 'Garantir que todas as intervenções no domínio hídrico cumprem a legislação em vigor.', 'EE', 2, 15);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('11.5', 'Adotar as práticas e medidas adequadas de modo a reduzir a formação de poeiras na origem, por compactação e pulverização do solo, visando também a redução dos níveis de perda de carbono e de libertação de poeiras e a sua propagação, como: o não uso de máquinas de rastos; redução das movimentações de terras em períodos de ventos e a exposição de solo nu nos períodos de maior pluviosidade e ventos.', 'EE', 2, 16);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('12', 'Em todas as áreas sujeitas a intervenção, e antes do início de qualquer atividade relacionada com a obra, devem ser estabelecidos os limites para além do quais não deve haver lugar a qualquer perturbação, quer pelas máquinas quer por eventuais depósitos de terras e/ou outros materiais de forma a reduzir a compactação dos solos. No caso da circulação de veículos, e máquinas, deve a mesma realizar-se de forma controlada, fundamentalmente, dentro de corredores balizados. Consequentemente, os referidos limites devem ser claramente balizados considerando uma área de proteção em torno das mesmas, e não meramente sinalizados, antes do início da obra, devendo permanecer em todo o perímetro, durante a execução da mesma.', 'EE | RAA', 2, 17);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('13', 'Em torno de todos os exemplares arbóreos a preservar, e eventualmente arbustivos, se aplicável, quando próximos de áreas intervencionadas, deve ser criada uma área de proteção, no mínimo correspondente a do diâmetro da copa. A balizagem, enquanto medida preventiva e de proteção, deve ser executada em todo o perímetro da linha circular de projeção horizontal da copa, sobre o terreno, do exemplar arbóreo em causa, ou, no mínimo, na extensão voltada para o lado da intervenção.', 'EE | RAA', 2, 18);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('14', 'Considerar a recolha de espécies ou transplantes das que estão presentes nos Biótopos "Prados", "Ripícola" e "Dunar" - Dunas Cinzentas - para serem utilizadas nas áreas dos projetos de integração paisagística.', 'EE | RAA', 2, 19);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('15', 'A equipa dos trabalhos de arqueologia deve estar dimensionada de acordo com os trabalhos previstos efetuar. Esta deve integrar arqueólogos com experiência comprovada na vertente náutica e subaquática superior a 10 anos em registo e escavação subaquática, bem como integrar conservadores-restauradores para definir e implementar as ações de conservação e monitorização.', 'EE | RAP', 2, 20);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('16', 'Executar as eventuais propostas de minimização complementares definidas aquando da identificação dos valores patrimoniais até a presente fase.', 'EE | RAP', 2, 21);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('17', 'Implementar os estaleiros nos locais propostos no RECAPE e na pronúncia apresentada pelo proponente em sede de audiência prévia.', 'EE', 4, 22);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('18', 'As áreas dos estaleiros não devem ser impermeabilizadas, com exceção dos locais de manuseamento e armazenamento de substâncias poluentes. No caso dos produtos perigosos deve ser garantida a construção de uma bacia de retenção, impermeabilizada e isolada da rede de drenagem natural.', 'EE | RAA', 4, 23);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('19', 'Proceder à vedação das áreas de estaleiro, ou na sua impossibilidade, delimitação da área afeta ao mesmo com sinalização visível. Na vedação devem ser colocadas placas avisadoras que incluam as regras de segurança a observar, assim como a calendarização das obras.', 'EE | RAA', 4, 24);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('20', 'Recorrer a mão-de-obra local ou regional, sempre que possível, e promover as ações (preventivas} de formação necessárias ao adequado desempenho das funções requeridas.', 'DO | EE', 4, 25);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('21', 'Assegurar que a iluminação que possa ser usada no exterior, incluindo estaleiros, não é projetada de forma intrusiva sobre a envolvente e sobre as habitações próximas sempre que aplicável. Nesse sentido, a mesma deve ser o mais dirigida possível para baixo, segundo a vertical, e apenas sobre os locais que efetivamente a exigem.', 'EE', 4, 26);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('22', 'Realizar os trabalhos de desmatação e desarborização deverão ser realizados fora da época de reprodução da maioria das espécies: de março a final de junho.', 'DO | EE', 5, 27);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('23', 'Realizar as ações de corte de vegetação deverão ser realizadas de forma gradual e reduzidas ao mínimo indispensável à execução dos trabalhos de modo a reduzir o tempo de exposição do solo.', 'EE', 5, 28);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('24', 'Os trabalhos desarborização, desmatação e decapagem de solos deverão ser limitados às áreas estritamente necessárias à execução dos trabalhos, devendo proceder-se à balizagem prévia das áreas a intervencionar. Para o efeito:', 'EE', 5, 29);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('24.1', 'Previamente ao início das intervenções, o limite das áreas de implantação deve ser sinalizado. Enquanto não for aplicada a vedação perimetral definitiva, a delimitação pode ser feita provisoriamente, embora de forma clara.', 'EE', 5, 30);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('24.2', 'Estaleiro: o estaleiro deverá ser vedado em toda a sua extensão.', 'EE', 5, 31);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('24.3', 'Devem ser delimitados os locais provisórios de depósitos de terras.', 'EE', 5, 32);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('24.4', 'Devem ser delimitadas outras zonas de armazenamento de materiais e equipamentos, que pela sua dimensão não podem ser armazenados no estaleiro.', 'EE', 5, 33);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('24.5', 'Áreas a intervencionar para instalação dos apoios das Linhas elétricas, área de apoio à montagem e respetivos acessos.', 'EE', 5, 34);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('25', 'O corte dos sobreiros deve ser horizontal ou ligeiramente inclinado, executado rente ao solo e com superfície absolutamente lisa.', 'EE | RAA', 5, 35);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('26', 'Evitar o abate e afetação de sobreiros na implantação dos apoios e acessos, sempre que tecnicamente possível.', 'EE | RAA', 5, 36);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('27', 'Não podem ser efetuadas escavações não previstas na proximidade de sobreiros ou azinheiras, devendo ser respeitada uma distância de segurança correspondente ao dobro do raio da copa, no mínimo de 4 m de raio (árvores jovens), quer no que respeita aos acessos a criar ou a reabilitar, quer no que diz respeito à preparação da área de trabalho a criar junto de cada apoio. Se com esta limitação surgirem situações em que não seja possível criar acessos com condições para circulação de autobetoneiras, o betão terá de ser feito junto a cada apoio, e o transporte de material e matéria-prima necessária deve ser feito em trator.', 'EE | RAA', 5, 37);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('28', 'Caso a implementação da faixa de proteção da linha ou da faixa de gestão de combustível, implique o abate ou afetação de sobreiros ou azinheiras, esta ação deve ser comunicada ao ICNF e deve existir compensação, com os mesmos valores que se encontram definidos no Projeto de Compensação pelo abate e afetação de sobreiros.', 'DO | EE', 5, 38);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('29', 'No corredor da linha elétrica devem ser mantidas, sempre que possível, as unidades de vegetação natural e seminatural. Caso os exemplares arbóreos ponham em causa a segurança da linha, estes devem ser sujeitos a técnicas de poda, em detrimento do seu corte. Esta medida aplica-se sobretudo para indivíduos das espécies Quercus suber (sobreiro) e Quercus rotundifofia (azinheira).', 'EE | RAA', 5, 39);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('30', 'A terra viva/vegetal proveniente das operações de decapagem, possuidora do banco de sementes das espécies autóctones, deve ser removida e depositada em pargas. Estas devem ter até 3 m de altura; devem ser colocadas próximo das áreas de onde foram removidas, mas assegurando que tal se realiza em áreas planas e bem drenadas; e devem ser protegidas contra a erosão hídrica e eólica através de uma sementeira de leguminosas e/ou da sua cobertura, se necessário e aplicável, em função dos tempos de duração e das condições atmosféricas.', 'EE', 5, 40);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('31', 'Não utilizar solo vivo proveniente da decapagem que esteja contaminado com propágulos das espécies vegetais exóticas invasoras e assegurar o seu depósito, devidamente acondicionado ou colocado em níveis de profundidade superiores a 1 m.', 'EE | RAA', 5, 41);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('32', 'Em caso de ser necessário utilizar terra vegetal, terras de empréstimo e materiais inertes, a utilizar na construção dos novos acessos, enchimento de fundações e, eventuais, outras áreas, assegurar junto dos fornecedores que não provêm de áreas ou de stocks contaminadas por espécies vegetais exóticas invasoras ou estão isentos da presença dos respetivos propágulos/sementes das referidas espécies para que as mesmas não alterem a ecologia local e introduzam plantas invasoras.', 'EE | RAA', 5, 42);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('33', 'Os trabalhos de escavações e aterros devem ser iniciados logo que os solos estejam limpos, evitando repetição de ações sobre as mesmas áreas.', 'EE', 6, 43);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('34', 'A execução de escavações e aterros deve ser interrompida em períodos de elevada pluviosidade e devem ser tomadas as devidas precauções para assegurar a estabilidade dos taludes e evitar o respetivo deslizamento.', 'EE', 6, 44);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('35', 'Sempre que possível, utilizar os materiais provenientes das escavações como material de aterro, de modo a minimizar o volume de terras sobrantes (a transportar para fora da área de intervenção).', 'EE', 6, 45);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('36', 'Os produtos de escavação que não possam ser aproveitados, ou em excesso, devem ser armazenados em locais com características adequadas para depósito.', 'EE', 6, 46);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('37', 'Caso se verifique a existência de materiais de escavação com vestígios de contaminação, estes devem ser armazenados em locais que evitem a contaminação dos solos e das águas subterrâneas, por infiltração ou escoamento das águas pluviais, até esses materiais serem encaminhados para destino final adequado.', 'EE', 6, 47);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('38', 'Garantir o escoamento das linhas de água superficiais em todas as fases de obra.', 'EE', 6, 48);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('39', 'As terras sobrantes devem ser preferencialmente reutilizadas nos aterros previstos neste projeto ou no paisagismo, ou ainda utilizadas noutras obras (como subproduto). O envio das terras sobrantes para operador de gestão de resíduos deve ser feito em último recurso de modo a diminuir os impactes negativos relacionados com o transporte e deposição daquelas terras.', 'EE', 6, 49);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40', 'Caso haja necessidade de levar a depósito terras sobrantes, este deverá ser efetuado em locais legalmente autorizados. A seleção dessas zonas de depósito deve excluir as seguintes áreas: áreas urbanas e/ou turísticas; Zonas de proteção do património:', 'EE', 6, 50);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.1', 'Áreas do domínio público hídrico.', 'EE', 6, 51);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.2', 'Áreas inundáveis.', 'EE', 6, 52);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.3', 'Zonas de proteção de águas subterrâneas (áreas de elevada infiltração).', 'EE', 6, 53);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.4', 'Perímetros de proteção de captações.', 'EE', 6, 54);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.5', 'Áreas classificadas da Reserva Agrícola Nacional (RAN) ou Reserva Ecológica Nacional (REN).', 'EE', 6, 55);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.6', 'Outras áreas com estatuto de proteção, nomeadamente no âmbito da conservação da natureza.', 'EE', 6, 56);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.7', 'Outras áreas onde possam ser afetadas espécies de flora e de fauna protegidas por lei, nomeadamente sobreiros e/ou azinheiras.', 'EE', 6, 57);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.8', 'Locais sensíveis do ponto de vista geotécnico.', 'EE', 6, 58);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.9', 'Locais sensíveis do ponto de vista paisagístico.', 'EE', 6, 59);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.10', 'Áreas de ocupação agrícola.', 'EE', 6, 60);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.11', 'Proximidade de áreas urbanas e/ou turísticas.', 'EE', 6, 61);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('40.12', 'Zonas de proteção do património.', 'EE', 6, 62);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41', 'No caso se venha a revelar necessário recorrer a terras de empréstimo para a execução das obras, as terras deverão ser provenientes de locais legalmente autorizados. Devem ser respeitados os seguintes aspetos para a seleção dos locais de empréstimo:', 'EE', 6, 63);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.1', 'As terras de empréstimo devem ser provenientes de locais próximos do local de aplicação, para minimizar o transporte.', 'EE', 6, 64);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.2', 'As terras de empréstimo não devem ser provenientes de: terrenos situados em linhas de água, leitos e margens de massas de água', 'EE', 6, 65);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.3', 'Zonas ameaçadas por cheias.', 'EE', 6, 66);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.4', 'Zonas de infiltração elevada.', 'EE', 6, 67);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.5', 'Perímetros de proteção de captações de água.', 'EE', 6, 68);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.6', 'Áreas classificadas da RAN ou da REN.', 'EE', 6, 69);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.7', 'Áreas classificadas para a conservação da natureza.', 'EE', 6, 70);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.8', 'Outras áreas onde as operações de movimentação das terras possam afetar espécies de flora e de fauna protegidas por lei, nomeadamente sobreiros e/ou azinheiras.', 'EE', 6, 71);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.9', 'Locais sensíveis do ponto de vista geotécnico.', 'EE', 6, 72);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.10', 'Locais sensíveis do ponto de vista paisagístico.', 'EE', 6, 73);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.1', 'Áreas com ocupação agrícola.', 'EE', 6, 74);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.11', 'Área na proximidade de áreas urbanas e/ou turísticas.', 'EE', 6, 75);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.12', 'Zonas de proteção do património.', 'EE', 6, 76);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('41.13', 'No caso se venha a revelar necessário recorrer a terras de empréstimo para a execução das obras, as terras deverão ser provenientes de locais legalmente autorizados. Devem ser respeitados os seguintes aspetos para a seleção dos locais de empréstimo:', 'EE', 6, 77);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('42', 'Privilegiar o uso de caminhos já existentes para aceder aos locais da obra.', 'EE', 7, 78);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('43', 'Definir corredores de circulação, de forma a evitar a circulação indiscriminada nas áreas/terrenos adjacentes.', 'EE', 7, 79);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('44', 'Assegurar o correto cumprimento das normas de segurança e sinalização de obras na via pública, tendo em consideração a segurança e a minimização das perturbações na atividade das populações.', 'EE', 7, 80);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('45', 'Garantir a limpeza regular dos acessos e da área afeta à obra, de forma a evitar a acumulação e suspensão de poeiras, quer por ação do vento, quer por ação da circulação de veículos e de equipamentos de obra.', 'EE', 7, 81);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('46', 'Deve ser dada atenção especial à origem/proveniência, e condições de armazenamento, de todos materiais inertes para a construção dos acessos, ou terras de empréstimo se aplicável, não devendo ser provenientes em caso algum, de áreas ocupadas por espécies vegetais exóticas invasoras, para que as mesmas não alterem a ecologia local e introduzam plantas invasoras.', 'EE', 7, 82);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('47', 'Assegurar a não afetação de leito de cheia em resultado da movimentação de máquinas.', 'EE', 8, 83);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('48', 'Garantir as acessibilidades e espaço de estacionamento privilegiado destinado aos organismos afetos ao socorro a envolver em situações de acidente/emergência. Em especial na fase de construção, tendo particular atenção ao eventual aumento do fluxo de transito provocado pela movimentação de veículos afetos as obras, os trabalhos a desenvolver não devem comprometer a operacionalidade das ações de proteção civil e socorro, devendo ser equacionadas alternativas que salvaguardem a passagem de veículos afetos ao socorro e emergência.', 'DO | EE', 8, 84);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('49', 'Seleção preferencial de equipamentos que utilizem fluídos naturais ou gases fluorados com menor potencial de aquecimento global, quando disponíveis.', 'EE', 8, 85);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('50', 'Sempre que a travessia de zonas habitadas for inevitável, deve ser efetuada a velocidade muito reduzida (20 km/h), de forma a minimizar a emissão de poeiras e o incómodo para as populac6es em termos de ruído.', 'EE', 8, 86);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('51', 'Assegurar que as operações de construção mais ruidosas, que se desenrolem na proximidade de recetores sensíveis, apenas podem ocorrer em dias úteis, das 08:00h às 20:00h, não se considerando admissível qualquer extensão do horário de trabalho e das operações de construção.', 'EE', 8, 87);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('52', 'Proceder à manutenção e revisão periódica de todas as máquinas e veículos afetos à obra, de forma a manter as normais condições de funcionamento e assegurar a minimização das emissões gasosas.', 'EE', 8, 88);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('53', 'Assegurar o transporte de materiais de natureza pulverulenta ou do tipo particulado em veículos adequados, com a carga coberta, de forma a impedir a dispersão de poeiras.', 'EE', 8, 89);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('54', 'Verificar periodicamente as condições de segurança dos equipamentos a utilizar durante a execução dos trabalhos, com o objetivo de prevenir eventuais fugas de lubrificantes, combustíveis e emissões gasosas.', 'EE', 8, 90);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('55', 'Proceder à aspersão regular e controlada de água, sobretudo durante os períodos secos e ventosos, nas zonas de trabalhos e nos acessos utilizados pelos diversos veículos, onde poderá ocorrer a produção, acumulação e suspensão de poeiras.', 'EE', 8, 91);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('56', 'Assegurar que os caminhos ou acessos nas imediações da área do projeto não fiquem obstruídos ou em más condições, possibilitando a sua normal utilização por parte da população local. A saída de veículos das zonas de estaleiros e das frentes de obra para a via pública deverá obrigatoriamente ser feita de forma a evitar a sua afetação por arrastamento de terras e lamas pelos rodados dos veículos.', 'EE', 8, 92);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('57', 'Assegurar que são selecionados os métodos construtivos e os equipamentos que originem o menor ruído possível.', 'EE', 8, 93);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('58', 'Garantir a presença em obra unicamente de equipamentos que apresentem homologação acústica nos termos da legislação aplicável e que se encontrem em bom estado de conservação/manutenção.', 'EE', 8, 94);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('59', 'Proceder à manutenção e revisão periódica de todas as máquinas e veículos afetos à obra, de forma a manter as normais condições de funcionamento e assegurar a minimização das emissões gasosas, dos riscos de contaminação dos solos e das águas, e de forma a dar cumprimento às normas relativas à emissão de ruído.', 'EE', 8, 95);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('60', 'Adotar soluções estruturais e construtivas dos órgãos e edifícios, e instalação de sistemas de insonorização dos equipamentos e/ou edifícios que alberguem os equipamentos mais ruidosos, de modo a garantir o cumprimento dos limites estabelecidos no RGR e RRAE.', 'EE', 8, 96);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('61', 'Garantir condições de acessibilidade e operação dos meios de socorro, tanto na fase de construção como de exploração.', 'EE', 8, 97);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('62', 'O armazenamento de produtos/materiais deve ser assegurado em locais apropriados para o efeito. No caso dos produtos perigosos deve ser garantida a construção de uma bacia de retenção, impermeabilizada e isolada da rede de drenagem natural.', 'EE', 9, 98);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('63', 'Os estaleiros e as diferentes frentes de obra devem estar equipados com todos os materiais e meios necessários, que permitam responder em situações de incidentes/acidentes ambientais, nomeadamente derrames de substâncias poluentes.', 'EE', 9, 99);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('64', 'Implementar um adequado sistema de recolha e tratamento de águas residuais, o qual deve ter em atenção as diferentes caraterísticas dos efluentes gerados durante a fase de obra e atender aos seguintes pressupostos:', 'EE', 9, 100);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('64.1', 'Privilegiar a reutilização da água proveniente da limpeza de qualquer tipo de maquinaria, que contenha cascalho, areia, cimento ou inertes similares, após tratamento. Os inertes que resultem do processo de tratamento devem ser recolhidos e encaminhadas para destino final adequado.', 'EE', 9, 101);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('64.2', 'As águas que contenham, ou potencialmente possam conter substâncias químicas, assim como as águas com elevada concentração de óleos e gorduras, devem ser conduzidas para um depósito estanque, sobre terreno impermeabilizado, devendo posteriormente ser encaminhadas para destino final adequado.', 'EE', 9, 102);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('64.3', 'Os efluentes domésticos (serviços sanitários, cozinhas e refeitórios) devem ser devidamente encaminhados para uma fossa séptica estanque ou, em alternativa, tratados antes de serem descarregados no meio recetor. Ao proceder-se à limpeza da fossa, os efluentes e lamas devem ser encaminhados para destino final adequado. Caso seja viável, os efluentes deverão ser encaminhados para um sistema de gestão de águas residuais.', 'EE', 9, 103);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('64.4', 'A recolha dos efluentes provenientes de instalações sanitárias do tipo “móvel” deve garantir a frequência necessária à manutenção das boas condições de higiene, devendo ser realizada por uma empresa licenciada para o efeito.', 'EE', 9, 104);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('65', 'Os resíduos suscetíveis de gerar efluentes contaminados pela ação da percolação das águas pluviais devem ser armazenados em parque coberto.', 'EE', 9, 105);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('66', 'Assegurar a existência de um mapa de registo de quantidades de todas as tipologias de efluentes produzidos em obra, bem como dos consumos de água (humano e industrial).', 'EE', 9, 106);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('67', 'De modo a evitar acidentes, no armazenamento temporário de resíduos perigosos (classificação LER), preservar uma distância mínima de 15 m às margens de linhas de água permanentes ou temporárias.', 'EE', 9, 107);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('68', 'Toda a maquinaria deve ser devidamente inspecionada por forma a garantir o seu correto funcionamento, diminuindo risco de fugas e derrames acidentais e consequente contaminação dos solos e recursos hídricos.', 'EE', 9, 108);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('69', 'Não é permitida a rejeição de qualquer tipo de resíduos, ainda que provisória, nas margens, leitos de linhas de água e zonas de máxima infiltração.', 'EE', 9, 109);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('70', 'O atravessamento de máquinas em leito de cheia deve, preferencialmente, ser efetuado através de estruturas já existentes para o efeito, de forma a afetar o mínimo possível a vegetação ripícola e o próprio leito de cheia. Caso se preveja intercetar linhas de água, para estabelecimento de acessos à obra, têm as mesmas de ser estabelecidas por passagem hidráulica, ainda que a afetação ocorra por um curto período.', 'EE', 9, 110);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('71', 'Na eventual afetação de linhas de água e da vegetação ripícola associada, para além da recuperação da topografia original do leito e das margens deve ser garantida a reposição dos maciços arbustivos, assim como do número de exemplares arbóreos abatidos.', 'EE', 9, 111);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('72', 'Garantir a desobstrução e limpeza de todos os elementos hidráulicos de drenagem que possam ter sido afetados pelas atividades relacionadas com a empreitada. Na sequência da desmatação, da circulação de veículos pesados ou de qualquer outra intervenção na fase de construção deve ser assegurado que as linhas de água, valas e valetas não se encontram assoreados com material proveniente da obra ou resultante das obras (solos, resíduos, material de construção, etc.), que não existem empoçamentos importantes, que não existem riscos de deslizamentos ou ravinamentos importantes junto a linhas de água.', 'EE', 9, 112);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('73', 'No decurso dos trabalhos deverá ser dada especial atenção aos poços e furos existentes na área envolvente, devendo ser evitado qualquer tipo de interferência, nomeadamente aquelas que ponham em causa a integridade do recurso água. Todas as captações de água subterrânea existentes na proximidade dos locais de intervenção devem ser sinalizadas, e vedadas se existir a possibilidade de virem a ser afetadas pela obra e, no caso de poços não cobertos, deve ainda ser avaliada a necessidade da sua cobertura', 'EE', 9, 113);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('74', 'Assegurar a prospeção arqueológica sistemática dos locais de implantação das infraestruturas do projeto, que coincidam com zonas de visibilidade deficiente ou não prospetadas anteriormente, após a desmatação e antes das operações de decapagem e escavação, com a finalidade de colmatar as lacunas de conhecimento.', 'EE | RAP', 10, 114);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('75', 'Avisar a equipa de acompanhamento arqueológico sobre a previsão das ações relacionadas com a remoção e revolvimento do solo (desflorestação/desmatação e decapagem superficiais em ações de preparação e regularização do terreno) e escavações no solo e subsolo com uma antecedência mínima de 8 dias.', 'DO | EE', 10, 115);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('76', 'Assegurar o acompanhamento arqueológico integral, permanente e presencial, de todas as operações que impliquem movimentações dos solos em meio terrestre e subaquático, nos trabalhos iniciados e nas fases preparatórias, como a instalação do estaleiro, abertura/alargamento de acessos ou desmatação. O acompanhamento deve ser continuado e efetivo pelo que se houver mais que uma frente de obra em simultâneo terá de se garantir o acompanhamento de todas as frentes.', 'EE | RAP', 10, 116);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('77', 'As ações de limpeza ou desassoreamento devem ser acompanhadas, nos mesmos termos, por um arqueólogo em cada uma das dragas e um no local de deposição dos sedimentos. A equipa deve estar em permanente contacto, ter garantidas condições de segurança e capacidade de visualização dos trabalhos durante o trabalho, nomeadamente em horário noturno, a fim de, minimizar o risco de perda de bens e destruição de estruturas náuticas ou navais.', 'EE | RAP', 10, 117);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('78', 'As dragas utilizadas devem dispor de um dispositivo de visualização tridimensional de deteção de obstáculos {Obstacles Avoidance Sonar/ OAS} e uma grelha na cabeça da draga com uma malha até 20 cm que permita detetar eventuais vestígios arqueológicos submersos não identificados nos trabalhos arqueológicos. Estas devem ainda ser autopropulsionadas e terem capacidade de posicionamento estável pelos seus próprios meios. A draga ou outra embarcação que lhe esteja afeta deve dispor de equipamento adequado ao controlo em contínuo do seu trabalho.', 'EE | RAP', 10, 118);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('79', 'Realizar trabalhos de prospeção arqueológica com recurso a detetores de metais nas áreas de deposição de dragados em meio terrestre.', 'EE | RAP', 10, 119);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('80', 'Caso venham a ser encontrados vestígios arqueológicos na frente de obra, os trabalhos serão de imediato suspensos nessa frente de obra, ficando o arqueólogo obrigado a comunicar de imediato a situação a tutela, propondo as soluções que considerar mais convenientes com o objetivo de minimizar os impactes. Deve ser tido em considera<ao que as áreas com vestígios arqueológicos conservados e que venham a ser afetados de forma irreversível tem de ser integralmente escavados.', 'EE | RAP', 10, 120);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('81', 'As ocorrências arqueológicas que forem reconhecidas durante o acompanhamento arqueológico da obra devem, tanto quanto possível, e em função do seu valor patrimonial, ser conservadas in situ (mesmo que de forma passiva), de tal forma que não se degrade o seu estado de conservação atual. Os achados móveis devem ser colocados em depósito credenciado pelo organismo de tutela do património cultural. Contudo, perante o elevado potencial arqueológico de toda a área alvo de afetação do projeto, a eventual necessidade de exumação de espólio arqueológico, onde algum desse espólio pode ser sujeito a um acelerado processo de decomposição, implica a criação de uma ou mais reservas submersas primárias e transitórias até a sua entrega a Tutela do Património, para depositar esses bens móveis, protegendo-os assim da degradação irreversível a que ficarão sujeitos se permanecerem em contacto direto com o ambiente atmosférico durante a fase de execução. Desta forma, na equipa deve ter um elemento de conservação e restauro, especializado na área do tratamento e conservação de espólio resultante de meio submerso.', 'EE | RAP', 10, 121);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('82', 'Garantir a salvaguarda pelo registo arqueológico da totalidade dos vestígios e contextos a afetar diretamente pela obra, independentemente do seu meio. No caso de elementos arquitetónicos, através de registo gráfico, fotográfico e da elaboração de memória descritiva; no caso de sítios arqueológicos, através da sua escavação integral. Complementarmente podem ser necessários trabalhos de conservação e restauro.', 'EE | RAP', 10, 122);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('83', 'Proceder a uma caracterização e avaliação regular dos bens e contextos arqueológicos identificados, bem como em alguns locais aleatórios da área dragada numa área minimamente representativa. Este trabalho pode implicar a prospeção arqueológica visual e por mergulho com escafandro autónomo.', 'EE | RAP', 10, 123);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('84', 'Proceder, em caso de identificação de bens isolados e das estruturas náuticas, a datações radiométricas {do tipo wiggle-match}, análises estruturais, dendrocronológicas, caracterização e identificação da madeira, entre outras, nomeadamente sobre elementos cujos contextos arqueológicos não permitam atribuir uma cronologia clara. Deve-se ainda assegurar a recolha de amostras de madeira para outras análises.', 'EE | RAP', 10, 124);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('85', 'Assegurar a conservação preventiva para os bens e as estruturas arqueológicas alvo de trabalhos arqueológicos, evitando a degradação irreversível a que ficarão sujeitos durante a fase de execução. A exumação de espólio arqueológico, implica a criação de uma ou mais reservas primárias e transitórias, a definição das metodologias de transporte, acondicionamento, registo e inventariação.', 'EE | RAP', 10, 125);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('86', 'Os achados móveis colhidos no decurso da obra devem ser colocados em depósito credenciado pelo organismo de tutela do património cultural.', 'EE | RAP', 10, 126);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('87', 'Proceder à desativação da área afeta aos trabalhos para a execução da obra, com a desmontagem dos estaleiros e remoção de todos os equipamentos, maquinaria de apoio, depósitos de materiais, entre outros. Proceder à limpeza destes locais, no mínimo com a reposição das condições existentes antes do início dos trabalhos.', 'EE', 12, 127);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('88', 'Assegurar a reposição e/ou substituição de eventuais infraestruturas, equipamentos e/ou serviços existentes nas zonas em obra e áreas adjacentes, que sejam eventualmente afetadas no decurso da obra.', 'EE', 12, 128);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('89', 'Proceder à reparação do pavimento eventualmente danificado nas estradas utilizadas nos percursos de acesso ao Data Center pela circulação de veículos pesados durante a construção.', 'EE', 12, 129);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('90', 'Proceder à recuperação de caminhos e vias utilizados como acesso aos locais de instalação dos apoios das Linhas elétricas e desativar os acessos abertos e que não tenham utilidade posterior. A recuperação inclui operações de limpeza e remoção de todos os materiais, de remoção completa de pavimentos existentes, de descompactação do solo, regularização/modelação do terreno, de forma tão naturalizada quanto possível e o seu revestimento com as terras vegetais, de forma a criar condições favoráveis à regeneração natural e crescimento da vegetação autóctone.', 'EE', 12, 130);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('91', 'Proceder à recuperação paisagística dos locais de empréstimo de terras, caso se constate a necessidade de recurso a materiais provenientes do exterior da área de intervenção.', 'EE', 12, 131);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('92', 'Assegurar o adequado funcionamento do sistema de arrefecimento térmico (captação e rejeição de água do mar) e da utilização das infraestruturas costeiras de proteção associadas, em articulação com a respetiva entidade gestora.', 'DO', 12, 132);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('93', 'Realizar auditorias energéticas com vista a identificação de melhorias ao nível da redução do consumo de energia, como a otimização de equipamentos, utilização de iluminação mais eficiente e a implementação de sistemas de monitorização e controlo avançados.', 'DO | EE', 12, 133);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('94', 'Definir e implementar um plano de inspeção de fugas dos equipamentos, de acordo com a legislação em vigor, atendendo a eventual utilização de gases fluorados nos equipamentos inerentes ao projeto em causa.', 'DO | EE', 12, 134);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('95', 'Deve ser assegurada pela entidade responsável pela exploração das linhas elétricas, a gestão do combustível numa faixa envolvente a projeção vertical dos cabos condutores exteriores, no âmbito do Sistema de Gestão Integrada de Fogos Rurais.', 'DO | EE', 12, 135);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('96', 'A desmatação e controlo da vegetação nos corredores das linhas elétricas deve ser efetuado sem recurso a herbicidas, devendo ser realizado por meios mecânicos, preferencialmente sem remexer o solo.', 'DO | EE', 12, 136);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('97', 'Assegurar a limpeza do material combustível na envolvente do Data Center, bem como nas respetivas vias de acesso, de modo a garantir a existência de uma faixa de segurança contra incêndios, no âmbito do Sistema de Gestão Integrada de Fogos Rurais.', 'DO | EE', 12, 137);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('98', 'Na aquisição de serviços (manutenção, fornecimento de materiais, fornecimento de bens e serviços) e contratação de mão-de-obra, privilegiar, sempre que possível, empresas da região, desta forma fomentando o emprego permanente e indireto originado pela exploração do Data Center.', 'DO', 12, 138);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('99', 'Garantir a aquisição de equipamentos com maior eficiência energética e hídrica.', 'DO', 12, 139);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('100', 'Proceder à manutenção e revisão periódica dos equipamentos, de forma a manter as normais condições de funcionamento e assegurar a minimização em termos de emissões de ruído e, ainda, para reduzir, na fonte, a poluição do ar.', 'DO | EE', 12, 140);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('101', 'Realização de ações de sensibilização dirigidas à população presente nas instalações, em qualquer momento, quanto as medidas de autoproteção a adotar em caso de ocorrência, ou iminência de ocorrência, de um qualquer dos riscos referidos, ou de outros que se venham a aferir como críticos para a salvaguarda de pessoas e bens, bem como assegurar-se a realização periódica de simulacros, tendo em linha de conta os principais riscos identificados, com o envolvimento dos Agentes de Proteção Civil e dos Serviços Municipais de Proteção Civil.', 'DO', 12, 141);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('102', 'Promover a utilização do transporte coletivo em detrimento do transporte individualizado, no sentido de reduzir o número de veículos rodoviários em circulação.', 'DO', 12, 142);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('103', 'Promover a utilização de frotas de veículos menos poluentes (Euro 5 e Euro 6) e a introdução de veículos elétricos.', 'DO', 12, 143);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('104', 'Promover a formação profissional de trabalhadores para áreas de apoio ao Data Center, com vista a sua integração futura na equipa da START Campus e/ou empresas fornecedoras associadas ao Data Center, através da criação de parcerias com escolas da região ou dando continuidade a projetos já em desenvolvimento, nomeadamente o Projeto CEDCE - parceria com a Escola Tecnológica do Litoral Alentejano, com vista a formação de técnicos para o suporte e manutenção de Data Centers.', 'DO', 12, 144);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('105', 'Promover junto das instituições de ensino universitário da região a adequação dos cursos universitários existentes ou criação de especializações em áreas de necessidade do Data Center, com vista a formar recursos humanos para a START Campus e outras empresas fornecedoras de serviços', 'DO', 12, 145);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('106', 'Colocar sinalização no acesso a instalação industrial, adequada a circulação de veículos pesados e a moderação da velocidade de circulação, devendo respeitar as normas de segurança, nomeadamente a redução da velocidade de circulação junto das povoações.', 'DO | EE', 12, 146);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('107', 'Fornecer aos empreiteiros e subempreiteiros a Planta de Condicionamentos atualizada com a implantação de todos os elementos patrimoniais identificados, quer no EIA e no RECAPE, quer com os que se venham a identificar na fase de construção, sempre que se desenvolverem ações de manutenção ou outros trabalhos.', 'DO', 12, 147);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('108', 'Sempre que ocorram trabalhos de manutenção, que envolvam alterações que obriguem a revolvimentos do subsolo, circulação de maquinaria e pessoal afeto, nomeadamente em áreas anteriormente não afetadas pela construção das infraestruturas (e que não foram alvo de intervenção}, deve efetuar-se o acompanhamento arqueológico destes trabalhos e cumpridas as medidas de minimização previstas para a fase de construção, quando aplicáveis.', 'DO | EE', 12, 148);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('109', 'Caso se verifique a execução de ações de limpeza ou desassoreamento, deve ser solicitado um parecer da Tutela do Património Cultural de forma a salvaguarda esses valores e onde podem ser definidas eventuais medidas de minimização, nomeadamente o acompanhamento arqueológico por uma equipa de arqueologia com experiência comprovada na vertente náutica e subaquática, previamente autorizada, e que esteja dimensionada em relação a dinâmica e volume de trabalhos a realizar.', 'DO | EE', 12, 149);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('110', 'Caso a manutenção da faixa de proteção da linha ou da faixa de gestão de combustível, implique o abate ou afetação de sobreiros ou azinheiras, esta ação deve ser comunicada ao ICNF e deve existir compensação, com os mesmos valores que se encontram definidos no Projeto de Compensação pelo abate e afetação de sobreiros.', 'DO | EE', 12, 150);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('111', 'Tendo em conta o horizonte de tempo de vida útil previsto para o projeto, e a dificuldade de prever as condições ambientais locais e os instrumentos de gestão territorial e legais que irão estar em vigor, deve o promotor, no último ano de exploração do projeto, apresentar a solução futura de ocupação da área de implantação do projeto, após a respetiva desativação. Se a alternativa passar pela desativação, deve ser apresentado um plano pormenorizado, contemplando nomeadamente:', 'DO | EE', 14, 151);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('111.1', 'A solução final de requalificação da área de implantação do Data Center, Subestação e das Linhas elétricas associadas, a qual deve ser compatível com o direito de propriedade, os instrumentos de gestão territorial e com o quadro legal então em vigor.', 'DO | EE', 14, 152);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('111.2', 'Ações de desmantelamento e obra.', 'DO | EE', 14, 153);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('111.3', 'Destino a dar a todos os elementos retirados.', 'DO | EE', 14, 154);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('111.4', 'Definição das soluções de acessos ou outros elementos a permanecer no terreno.', 'DO | EE', 14, 155);
INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES ('111.5', 'Plano de recuperação final de todas as áreas afetadas.', 'DO | EE', 14, 156);